import {STORAGE_KEY,money,seedState,nextDate,expires,addOffer,reserve,cancel,collect,impact} from './domain.js';
const $ = s => document.querySelector(s);
const esc = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;
try { const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null'); state=saved?.version===1&&Array.isArray(saved.offers)&&Array.isArray(saved.orders)?saved:seedState(); } catch {state=seedState();}
let category='All food',query='',maxPrice=1000000,maxDistance=100,viewMode='list',mapOffer='bakery',sort='distance';
const modal=$('#modal');
let lastFocused;
function commit(next) { try{localStorage.setItem(STORAGE_KEY,JSON.stringify(next));}catch{throw Error('Your browser could not save this change. Free some storage or use a regular browser window.');} state=next;render(); }
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function openModal(html){lastFocused=document.activeElement;$('#modal-content').innerHTML=html;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();lastFocused?.focus();}
$('.modal-close').addEventListener('click',closeModal);
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
modal.addEventListener('close',()=>lastFocused?.focus());
function dayLabel(date){const d=new Date(date+'T12:00:00');const today=new Date();if(d.toDateString()===today.toDateString())return'Today';const tomorrow=new Date();tomorrow.setDate(today.getDate()+1);if(d.toDateString()===tomorrow.toDateString())return'Tomorrow';return d.toLocaleDateString('en-GB',{day:'numeric',month:'short'});}
function pickup(o){return`${dayLabel(o.date)}, ${o.start}–${o.end}`;}
function currentView(){return ['discover','pickups','cafe','impact'].includes(location.hash.slice(1))?location.hash.slice(1):'discover';}
function updateNav(){const v=currentView();document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===v);if(a.dataset.nav===v)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const n=state.orders.filter(o=>o.status==='reserved'&&new Date(`${o.date}T${o.end}:00`).getTime()>Date.now()).length;$('#pickup-count').textContent=n||'';}
function render(){updateNav();({discover:renderDiscover,pickups:renderPickups,cafe:renderCafe,impact:renderImpact}[currentView()])();}
function visibleOffers(){return state.offers.filter(o=>o.stock>0&&expires(o)>Date.now()&&(category==='All food'||o.category===category)&&o.price<=maxPrice&&o.distance<=maxDistance&&(o.cafe+' '+o.title+' '+o.category).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='price'?a.price-b.price:a.distance-b.distance);}
function card(o){return`<article class="food-card"><div class="card-image"><img src="${esc(o.image)}" alt="Illustrative ${esc(o.category.toLowerCase())} food" loading="lazy"><span class="stock">${o.stock} ${o.stock===1?'bag':'bags'} left</span></div><div class="card-content"><div class="card-cafe"><span>${esc(o.cafe)}</span><span>~${o.distance.toFixed(1)} km</span></div><h3>${esc(o.title)}</h3><p class="pickup-time">Pickup ${pickup(o)}</p><div class="card-bottom"><div><span class="price">${money(o.price)}</span><span class="old-price">${money(o.original)}</span></div><button class="round-btn" data-offer="${esc(o.id)}" aria-label="View ${esc(o.title)}">↗</button></div></div></article>`;}
function renderDiscover(){
 $('#main').innerHTML=`<section class="hero"><div><div class="eyebrow">A little less waste. A little more good.</div><h1>Good food.<br><em>A second chance.</em></h1><p>Rescue delicious surplus from your neighborhood cafés. A smaller price for you, a better ending for good food.</p><a class="btn" href="#offers">Find your next bag <span aria-hidden="true">↗</span></a></div><div class="hero-image"><img src="assets/bread.jpg" alt="Freshly baked artisan bread"><div class="hero-label">Baked with care. Worth sharing.</div></div></section><section id="offers" aria-labelledby="offers-title"><div class="section-top"><h2 id="offers-title">Good finds around you</h2><p>Fictional cafés · Illustrative photos</p></div><div class="filters"><div class="categories" role="group" aria-label="Food category">${['All food','Bakery','Meals','Produce'].map(c=>`<button class="chip ${category===c?'selected':''}" data-category="${c}" aria-pressed="${category===c}">${c}</button>`).join('')}</div><label class="search"><span class="sr-only">Search offers</span><input type="search" id="search" placeholder="Search cafés or food" value="${esc(query)}" aria-label="Search offers"></label><select id="price-filter" aria-label="Maximum price"><option value="1000000">Any price</option><option value="1000">Under ₸1,000</option><option value="1500">Under ₸1,500</option><option value="2000">Under ₸2,000</option></select><select id="distance-filter" aria-label="Maximum distance"><option value="100">Any distance</option><option value="1">Within 1 km</option><option value="2">Within 2 km</option><option value="3">Within 3 km</option></select><select id="sort" aria-label="Sort offers"><option value="distance">Nearest first</option><option value="price">Lowest price</option></select><button class="chip" id="view-toggle">${viewMode==='list'?'Map view':'List view'}</button></div><div id="results"></div><p class="micro">Distances are illustrative estimates from central Astana. No live location tracking. Pickup times use your device’s local time.</p></section><section class="how-it-works" aria-label="How FoodShare works"><div><span>01 &nbsp;Find a little good</span><p>Browse surplus bags and check ingredients, prices and pickup times.</p></div><div><span>02 &nbsp;Make it yours</span><p>Reserve a bag in our demo. Your pickup code keeps the order easy to find.</p></div><div><span>03 &nbsp;Pick up with purpose</span><p>Show your code at pickup. We count impact only after the café confirms collection.</p></div></section>`;
 $('#price-filter').value=String(maxPrice);$('#distance-filter').value=String(maxDistance);$('#sort').value=sort;
 document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;renderDiscover();});
 $('#search').oninput=e=>{query=e.target.value;renderResults();};
 $('#price-filter').onchange=e=>{maxPrice=Number(e.target.value);renderResults();};
 $('#distance-filter').onchange=e=>{maxDistance=Number(e.target.value);renderResults();};
 $('#sort').onchange=e=>{sort=e.target.value;renderResults();};
 $('#view-toggle').onclick=()=>{viewMode=viewMode==='list'?'map':'list';renderDiscover();};renderResults();
}
function renderResults(){const offers=visibleOffers();const target=$('#results');if(!target)return;
 if(!offers.length){target.innerHTML='<div class="empty"><h2>No bags match this search</h2><p>Try another category or a higher price limit.</p><button class="btn secondary" id="clear-filters">Clear filters</button></div>';$('#clear-filters').onclick=()=>{category='All food';query='';maxPrice=1000000;maxDistance=100;renderDiscover();};return;}
 if(viewMode==='map'){const chosen=offers.find(o=>o.id===mapOffer)||offers[0];mapOffer=chosen.id;target.innerHTML=`<div class="map-layout"><div class="map-choices">${offers.map(o=>`<button class="map-choice ${o.id===mapOffer?'selected':''}" data-map="${esc(o.id)}"><strong>${esc(o.cafe)}</strong><span>${money(o.price)} · ~${o.distance.toFixed(1)} km<br>Demo location</span></button>`).join('')}<button class="btn" id="map-reserve">View this bag</button></div><div><iframe title="Approximate demo pickup location on OpenStreetMap" loading="lazy" src="https://www.openstreetmap.org/export/embed.html?bbox=71.405%2C51.115%2C71.455%2C51.142&amp;layer=mapnik&amp;marker=${chosen.lat}%2C${chosen.lng}"></iframe><p class="micro">OpenStreetMap © OpenStreetMap contributors. A fictional café location for demonstration.</p></div></div>`;document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{mapOffer=b.dataset.map;renderResults();});$('#map-reserve').onclick=()=>showOffer(mapOffer);}
 else{target.innerHTML=`<div class="cards">${offers.map(card).join('')}</div>`;document.querySelectorAll('[data-offer]').forEach(b=>b.onclick=()=>showOffer(b.dataset.offer));}
}
function showOffer(id){const o=state.offers.find(x=>x.id===id);if(!o)return;openModal(`<img class="modal-photo" src="${esc(o.image)}" alt="Illustrative ${esc(o.category)} food"><span class="eyebrow">${esc(o.cafe)}</span><h2 class="modal-title" id="modal-title">${esc(o.title)}</h2><p class="modal-body">${esc(o.description)}</p><div class="modal-facts"><div><strong>PICKUP WINDOW</strong>${pickup(o)}<br>${esc(o.address)}</div><div><strong>ALLERGEN INFORMATION</strong>${esc(o.allergens)}</div></div><p class="micro">Estimated ${o.kg.toFixed(1)} kg per bag. Contents vary. Demo reservation only. No money is charged.</p><form id="reserve-form"><label class="check-row"><input type="checkbox" id="allergen-confirm" required><span>I have read the allergen information and understand this is a simulated order.</span></label><div class="checkout"><label>Bags<input type="number" id="quantity" min="1" max="${o.stock}" value="1" required></label><div><span class="price" id="total">${money(o.price)}</span><div class="quantity-note">${o.stock} bags available</div></div><button type="submit" class="btn">Reserve demo bag</button></div><p id="reserve-error" class="error" role="alert"></p></form>`);
 $('#quantity').oninput=e=>{$('#total').textContent=money(o.price*Math.max(0,Number(e.target.value)||0));};
 $('#reserve-form').onsubmit=e=>{e.preventDefault();try{const token='FS-'+crypto.randomUUID().replaceAll('-','').slice(0,8).toUpperCase();const next=reserve(state,id,Number($('#quantity').value),token);commit(next);showTicket(token);toast('Demo reservation saved. No payment was taken.');}catch(err){$('#reserve-error').textContent=err.message;}};
}
function showTicket(id){const o=state.orders.find(x=>x.id===id);if(!o)return;openModal(`<div class="ticket"><span class="status ${o.status}">${esc(o.status)}</span><h2 id="modal-title" class="modal-title">Your next good pickup</h2><p class="modal-body">${esc(o.cafe)}<br>${esc(o.title)} · ${o.qty} ${o.qty===1?'bag':'bags'}<br>${pickup(o)}</p><div class="qr" id="qr"></div><div class="ticket-code">${esc(o.token)}</div><p class="micro">Show this QR code or enter the code in the café workspace.<br>Demo payment of ${money(o.total)}. No real charge.</p><div class="ticket-buttons"><button class="btn secondary" id="copy-code">Copy code</button><button class="btn" id="go-pickups">My pickups</button></div></div>`);
 if(typeof window.qrcode==='function'){const q=window.qrcode(0,'M');q.addData(o.token);q.make();$('#qr').innerHTML=q.createImgTag(6,4,`Pickup code ${o.token}`);}else{$('#qr').textContent='Use the pickup code below.';}
 $('#copy-code').onclick=async()=>{try{await navigator.clipboard.writeText(o.token);toast('Pickup code copied.');}catch{toast('Copy this code: '+o.token);}};
 $('#go-pickups').onclick=()=>{closeModal();location.hash='pickups';render();};
}
function renderPickups(){
 $('#main').innerHTML=`<div class="page-heading"><div class="eyebrow">A good thing to look forward to</div><h1>My pickups</h1><p>Your reservations live in this browser. Show the pickup code at collection, or cancel an active reservation before its pickup window ends.</p></div>${state.orders.length?`<div class="order-list">${state.orders.map(o=>{const expired=new Date(`${o.date}T${o.end}:00`).getTime()<=Date.now();return`<article class="order-row"><img src="${esc(o.image)}" alt="Illustrative food"><div><span class="status ${o.status}">${o.status==='reserved'&&expired?'expired':esc(o.status)}</span><h2>${esc(o.title)}</h2><p>${esc(o.cafe)} · ${o.qty} ${o.qty===1?'bag':'bags'} · ${money(o.total)}</p><p>${pickup(o)}</p></div><div class="order-actions">${o.status==='reserved'&&!expired?`<button class="btn" data-ticket="${esc(o.id)}">Pickup code</button><button class="text-button" data-cancel="${esc(o.id)}">Cancel reservation</button>`:`<span class="micro">${o.status==='collected'?'Thanks for giving good food a second chance.':o.status==='cancelled'?'Your bags returned to available stock.':'This pickup window has ended.'}</span>`}</div></article>`;}).join('')}</div>`:'<div class="empty"><h2>Your next good find is waiting</h2><p>Reserve a surplus bag to see its pickup details here.</p><a href="#discover" class="btn">Discover food</a></div>'}`;
 document.querySelectorAll('[data-ticket]').forEach(b=>b.onclick=()=>showTicket(b.dataset.ticket));
 document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{const id=b.dataset.cancel;openModal('<h2 class="modal-title" id="modal-title">Cancel this reservation</h2><p class="modal-body">The bags will return to the available stock. No real payment or refund is involved.</p><button class="btn danger" id="confirm-cancel">Cancel demo reservation</button><p class="error" id="cancel-error" role="alert"></p>');$('#confirm-cancel').onclick=()=>{try{commit(cancel(state,id));closeModal();toast('Reservation cancelled. The stock is available again.');}catch(err){$('#cancel-error').textContent=err.message;}};});
}
function renderCafe(){
 const pending=state.orders.filter(o=>o.status==='reserved');
 $('#main').innerHTML=`<div class="page-heading"><div class="eyebrow">For the people behind the counter</div><h1>Café workspace</h1><p>Publish a surplus bag and confirm a collection. This shared demo workspace has no authentication. Every café shown is fictional.</p></div><div class="workspace"><section class="panel"><h2>Give good food a second chance</h2><form id="offer-form"><div class="form-grid"><label>Café name<input name="cafe" value="Qala Bakery" maxlength="100" required></label><label>Category<select name="category"><option>Bakery</option><option>Meals</option><option>Produce</option></select></label><label class="full">Offer title<input name="title" placeholder="Evening bread bag" maxlength="100" required></label><label>Rescue price in ₸<input name="price" type="number" min="1" max="999999" step="1" placeholder="1200" required></label><label>Original price in ₸<input name="original" type="number" min="2" max="1000000" step="1" placeholder="3600" required></label><label>Bags available<input name="stock" type="number" min="1" max="100" step="1" value="5" required></label><label>Estimated kg per bag<input name="kg" type="number" min="0.01" max="50" step="0.01" value="0.7" required></label><label class="full">Pickup date<input name="date" type="date" min="${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,'0')}-${String(new Date().getDate()).padStart(2,'0')}" value="${nextDate()}" required></label><label>Pickup starts<input name="start" type="time" value="18:00" required></label><label>Pickup ends<input name="end" type="time" value="21:00" required></label><label class="full">Pickup address<input name="address" placeholder="Demo pickup address" maxlength="200" required></label><label class="full">What is in the bag<textarea name="description" maxlength="600" required placeholder="Describe the likely contents. The exact selection may vary."></textarea></label><label class="full">Ingredients and allergens<textarea name="allergens" maxlength="400" required placeholder="For example: wheat, milk, eggs. May contain nuts."></textarea></label><label class="full">Illustrative photograph<select name="image"><option value="assets/bread.jpg">Artisan bread</option><option value="assets/pastry.jpg">Pastries</option><option value="assets/salad.jpg">Fresh meal</option><option value="assets/produce.jpg">Vegetables</option></select></label><label class="full">Or upload a photo <span class="micro">JPG, PNG or WebP. Maximum 1 MB. Stored only in this browser.</span><input name="upload" type="file" accept="image/jpeg,image/png,image/webp"></label></div><p id="offer-error" class="error" role="alert"></p><button class="btn" type="submit">Publish demo offer <span aria-hidden="true">↗</span></button></form></section><aside class="workspace-right"><section class="panel"><h2>Confirm a pickup</h2><p>Enter the code shown on the buyer’s ticket or decoded by a QR reader. Camera scanning is outside this prototype. Early collection is allowed for the classroom demonstration.</p><form class="verify-form" id="verify-form"><input class="code-input" id="verify-code" aria-label="Pickup code" placeholder="FS-XXXXXXXX" required maxlength="11"><button class="btn" type="submit">Verify</button></form><p class="error" id="verify-error" role="alert"></p><div id="verification-success" role="status"></div></section><section class="panel"><h2>Awaiting collection</h2><p>${pending.length} active demo reservation${pending.length===1?'':'s'}. Count only confirmed collections as impact.</p><div class="mini-list">${pending.map(o=>`<div class="mini-row"><div>${esc(o.cafe)}<br><span>${esc(o.title)} · ${o.qty} bags</span></div><span>${new Date(`${o.date}T${o.end}:00`).getTime()<=Date.now()?'Expired':pickup(o)}</span></div>`).join('')||'<p>No active reservations yet.</p>'}</div></section><section class="panel"><h2>Your demo inventory</h2><div class="mini-list">${state.offers.map(o=>`<div class="mini-row"><div>${esc(o.title)}<br><span>${esc(o.cafe)}</span></div><strong>${o.stock} bags</strong></div>`).join('')}</div></section></aside></div>`;
 $('#offer-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;const f=new FormData(form);try{let image=String(f.get('image'));const file=f.get('upload');if(file?.size){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>1024*1024)throw Error('Please upload a JPG, PNG or WebP photo smaller than 1 MB.');image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('The photo could not be read.'));reader.readAsDataURL(file);});}const offer={id:crypto.randomUUID(),cafe:String(f.get('cafe')).trim(),title:String(f.get('title')).trim(),category:String(f.get('category')),price:Number(f.get('price')),original:Number(f.get('original')),stock:Number(f.get('stock')),kg:Number(f.get('kg')),date:String(f.get('date')),start:String(f.get('start')),end:String(f.get('end')),address:String(f.get('address')).trim(),description:String(f.get('description')).trim(),allergens:String(f.get('allergens')).trim(),distance:1.0,lat:51.1282,lng:71.4304,image};commit(addOffer(state,offer));toast('Your demo offer is live in Discover.');}catch(err){$('#offer-error').textContent=err.message;}};
 $('#verify-form').onsubmit=e=>{e.preventDefault();const code=$('#verify-code').value;try{const o=state.orders.find(x=>x.token===code.trim().toUpperCase());commit(collect(state,code));$('#verification-success').innerHTML=`<p class="saved-notice">Collection confirmed: ${esc(o.cafe)}, ${o.qty} bags. Impact updated.</p>`;toast('Pickup confirmed. Thank you for sharing good food.');}catch(err){$('#verify-error').textContent=err.message;}};
}
function renderImpact(){const i=impact(state);$('#main').innerHTML=`<div class="page-heading"><div class="eyebrow">Small actions. Measurable change.</div><h1>Every pickup counts</h1><p>These totals come only from collections confirmed in this browser. They start at zero and contain no invented transactions.</p></div><section class="metrics" aria-label="Demo impact"><div class="metric"><strong>${i.bags}</strong><span>demo bags collected</span></div><div class="metric"><strong>${i.kg.toFixed(1)} kg</strong><span>estimated food collected</span></div><div class="metric"><strong>${money(i.savings)}</strong><span>demo buyer savings</span></div><div class="metric"><strong>${money(i.revenue)}</strong><span>demo café revenue</span></div></section><section class="impact-detail"><h2>Food belongs<br>on someone’s table.</h2><p>Weight is the café’s estimate per bag multiplied by confirmed quantity. Revenue is the total demo rescue price. Savings compare the demo original price with the rescue price. Reservations and cancellations do not count.<br><br>These figures describe classroom activity. They do not establish measured food-waste reduction or avoided carbon emissions.</p></section><div class="section-top" style="margin-top:35px"><h2>The next step is yours</h2><a class="btn secondary" href="#discover">Discover a bag ↗</a></div>`;}
$('#about-button').onclick=()=>openModal(`<div class="about"><h2 id="modal-title" class="modal-title">About FoodShare</h2><p>A Project Management endterm prototype by Ruslan Bolatbekuly, Ayana Markhabat, Abilmansur Kassymov and Balgyn Yermakhanbet. Group SE-2404. Instructor Alimova Balaussa.</p><h3>What this prototype does</h3><p>Offer publishing, food discovery, price and category filtering, a map preview, simulated reservations, real QR generation, manual pickup verification, cancellation and a collection-based impact summary.</p><h3>Prototype boundaries</h3><p>All cafés and offers are fictional. Data stays in localStorage on this device. There is no shared database, secure account login, real payment, live geolocation, camera scanner or push notification. The café workspace is a role simulation. A production release needs server-side validation and atomic inventory updates.</p><h3>Image and code credits</h3><p>Illustrative photos: <a href="https://unsplash.com" target="_blank" rel="noopener">Unsplash</a>. Map: © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>. QR code library by Kazuhiko Arase, MIT license. Source credits are included with the project.</p><h3>Restart the demonstration</h3><p>Reset clears this browser’s demo offers and orders. Your report and presentation are unaffected.</p><button class="btn danger" id="reset-demo">Reset demo data</button></div>`);
document.addEventListener('click',e=>{if(e.target.id==='reset-demo'){openModal('<h2 id="modal-title" class="modal-title">Start the demo again</h2><p class="modal-body">This clears the offers and orders saved in this browser and restores the four example bags.</p><button id="confirm-reset" class="btn danger">Reset this browser’s demo</button><p class="error" id="reset-error" role="alert"></p>');$('#confirm-reset').onclick=()=>{try{commit(seedState());closeModal();toast('Demo data reset.');}catch(err){$('#reset-error').textContent=err.message;}};}});
window.addEventListener('hashchange',()=>{if(location.hash==='#offers'){if(currentView()!=='discover')location.hash='discover';$('#offers')?.scrollIntoView({behavior:'smooth'});return;}render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){try{const s=JSON.parse(e.newValue);if(s?.version===1&&Array.isArray(s.offers)&&Array.isArray(s.orders)){state=s;render();}}catch{}}});
render();setInterval(()=>{if(currentView()==='discover')renderResults();},60000);
